import {state} from '../../core/state.js?v=9d97c650b6d2';
import {api,exportFile} from '../../core/api.js?v=9d97c650b6d2';
import {refresh} from '../../core/events.js?v=9d97c650b6d2';
import {T,esc,icon,heading,btn,panel,empty,modal,field,formEnd,closeModal,toast,date} from '../../core/ui.js?v=9d97c650b6d2';
export async function load(){}
export function render(){const s=state.workspace;return heading(T('Phiên bản dữ liệu','Dataset versions'),T('Chụp lớp nhãn, lưu checksum và giữ báo cáo tại thời điểm xuất bản phiên bản.','Capture annotation layers, checksums and quality reports at a point in time.'),btn(T('Chụp phiên bản','Create version'),'versions:create','primary','plus',s.project.can_manage?'':'disabled'))+panel(T('Lịch sử phiên bản','Version history'),s.versions.length?`<div class="version-timeline">${s.versions.map((v,i)=>`<article class="version-item"><span class="version-node">${icon('layers',17)}</span><div class="version-content"><div class="between"><div><span class="version-kicker">VERSION #${v.id}</span><h3>${esc(v.name)}</h3></div><span class="badge ${i===0?'green':'blue'}">${i===0?T('Mới nhất','Latest'):T('Snapshot','Snapshot')}</span></div><p>${date(v.created_at)} · ${v.count} ${T('bình luận','comments')}</p><code class="checksum">SHA-256: ${esc(v.sha256||T('Không khả dụng trong ngữ cảnh demo này','Unavailable in this demo context'))}</code><div class="flex gap8 mt16">${btn(T('Tải snapshot','Download snapshot'),'versions:download','','download',`data-id="${v.id}"`)}${btn(T('Khôi phục lớp nhãn','Restore annotation layers'),'versions:restore','','refresh',`data-id="${v.id}"`)}</div></div></article>`).join('')}</div>`:empty(T('Chưa có phiên bản','No versions yet'),T('Tạo snapshot trước mỗi thí nghiệm hoặc mốc bàn giao.','Create a snapshot before each experiment or handoff.')))+`<div class="info-banner mt24">${icon('shield',18)}<span>${T('Khôi phục tạo bản sao trước thay đổi, rồi phục hồi lớp nhãn người/gold trên mẫu cùng ID và văn bản. Những mẫu khác và nhãn lượt đầu nghiên cứu được giữ nguyên.','Restoring creates a backup, then restores human/gold layers on records with matching IDs and text. Other records and frozen research first-pass labels are retained.')}</span></div>`;}
export async function action(name,el){if(name==='create')modal(T('Chụp phiên bản','Create a version'),`<form data-submit="versions:create">${field('name',T('Tên phiên bản','Version name'),'','text','required maxlength="160" placeholder="v1 · trước thí nghiệm"')}${formEnd(T('Tạo snapshot','Create snapshot'))}</form>`);if(name==='download')await exportFile('studio/versions/'+el.dataset.id,`annotaflow-version-${el.dataset.id}.json`);if(name==='restore'){const v=state.workspace.versions.find(v=>v.id===Number(el.dataset.id));modal(T('Khôi phục lớp nhãn','Restore annotation layers'),`<form data-submit="versions:restore" data-id="${v.id}"><p class="form-hint">${T('Nhập đúng tên phiên bản để xác nhận. Backend sẽ chụp bản sao hiện tại trước khi khôi phục.','Type the version name to confirm. The backend captures a backup first.')}</p>${field('confirm',v.name,'','text','required')}${formEnd(T('Khôi phục','Restore'))}</form>`);}}
export async function submit(name,f){const v=Object.fromEntries(new FormData(f));await api(name==='create'?'studio/versions':`studio/versions/${f.dataset.id}/restore`,{project:state.workspace.project.id,...v});closeModal();await refresh();toast(T('Đã lưu phiên bản và lịch sử thay đổi.','Version history saved.'));}
